import time

def led(on):
    with open("/sys/class/gpio/gpio17/value", "w") as f:
        f.write("1" if on else "0")

def dot():
    led(True); time.sleep(UNIT);
    led(False); time.sleep(UNIT)

def dash():
    led(True); time.sleep(3 * UNIT)
    led(False); time.sleep(UNIT)

def send_symbol(char):
    seq = MORSE[char.upper()]
    for s in seq:
        dot() if s == '.' else dash()
    time.sleep(2 * UNIT)  # complète l'écart entre lettres (3 - 1 unité)

def send_message(text):
    for char in text:
        if char == ' ':
            time.sleep(4 * UNIT)  # complète l'écart entre mots (7 - 3 unités)
        else:
            send_symbol(char)

