def metrics():
    load = open("/proc/loadavg").read().split()
    mem = {}
    for line in open("/proc/meminfo"):
        k, v = line.split(':')
        mem[k] = int(v.strip().split()[0])
    return {
        "load1": float(load[0]),
        "load5": float(load[1]),
        "load15": float(load[2]),
        "uptime": float(open("/proc/uptime").read().split()[0]),
        "mem_total_mb": mem["MemTotal"] // 1024,
        "mem_available_mb": mem["MemAvailable"] // 1024,
    }

