import time
from pathlib import Path

def read_temp():
    p = Path("/sys/class/thermal/thermal_zone0/temp")
    return int(p.read_text().strip()) / 1000.0

print("moniteur demarre", flush=True)
while True:
    print(f"temperature={read_temp():.1f}C", flush=True)
    time.sleep(5)

